head.css:
@font-face {
  font-display: swap;
  font-family: 'EB Garamond';
  font-style: normal;
  font-weight: 400;
  src: url('/design/depoluxe.xyz/assets/fonts/eb-garamond-v32-latin-regular.woff2?v=41bbbb8671') format('woff2');
}

@font-face {
  font-display: swap;
  font-family: 'EB Garamond';
  font-style: italic;
  font-weight: 400;
  src: url('/design/depoluxe.xyz/assets/fonts/eb-garamond-v32-latin-italic.woff2?v=949b7bc18f') format('woff2');
}

head.code:
var IS_WEBP_SUPPORTED = false;
  var WEBP_EXTENSION = "";
  var webp = new Image();
  webp.onerror = function(){IS_WEBP_SUPPORTED = false};
  webp.onload = () => {IS_WEBP_SUPPORTED = true; WEBP_EXTENSION=".webp"};
  webp.src = 'data:image/webp;base64,UklGRjIAAABXRUJQVlA4ICYAAACyAgCdASoBAAEALmk0mk0iIiIiIgBoSygABc6zbAAA/v56QAAAAA==';

  const CMS_COLORS = {

      "primary": {
        hex: 0x000000,
        css: "#000000",
        str: "palette-primary"
      },

      "secondary": {
        hex: 0xffffff,
        css: "#ffffff",
        str: "palette-secondary"
      },

  }

  var LOADING_TIMER = new Date().getTime();

